//! Post-capture cross-check from raw streams, separate from the frozen phase reader.
use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,collections::{BTreeMap,BTreeSet}};
const R:&str="/home/ubuntu/src/zopro-perf-work/msm-local180";
fn read(p:&str)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn sha(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn near(a:f64,b:f64){assert!((a-b).abs()<1e-8,"{a} != {b}");}
fn main(){
 let jobs=read(&format!("{R}/jobs.json"));let rows=read(&format!("{R}/rows.json"));let review=read(&format!("{R}/review.json"));
 let mut phases=0;let mut timed=0;let mut exports=BTreeSet::new();let mut bounds=BTreeMap::<String,usize>::new();let mut faults=BTreeMap::<String,Vec<u64>>::new();let mut geometry=BTreeMap::<String,BTreeSet<String>>::new();
 for j in jobs.as_array().unwrap(){let name=j["name"].as_str().unwrap();let base=format!("{R}/run/{name}");for n in [name.to_owned(),format!("verify-{name}"),format!("inspect-{name}")]{let p=format!("{R}/run/{n}");let e=read(&format!("{p}/exit.json"));assert_eq!(e["success"],true);for(f,k)in [("stdout.log","stdout_sha256"),("stderr.log","stderr_sha256")]{assert_eq!(sha(&format!("{p}/{f}")),e[k].as_str().unwrap());}}
 let text=fs::read_to_string(format!("{base}/stdout.log")).unwrap();let z=j["mode"]=="zopro";let samples=text.lines().filter_map(|l|l.strip_prefix("SAMPLE ")).map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();let n=j["rounds"].as_u64().unwrap()as usize;assert_eq!(samples.len(),n);let mut times=vec![];for(i,s)in samples.iter().enumerate(){assert_eq!(s["round"],i);if !z{assert_eq!(s["cache_hit"],true);}times.push(s[if z{"ms"}else{"verified_ms"}].as_f64().unwrap());}timed+=n;
 let summary:Value=serde_json::from_str(text.lines().find_map(|l|l.strip_prefix("SUMMARY ")).unwrap()).unwrap();let stderr=fs::read_to_string(format!("{base}/stderr.log")).unwrap();let pp=stderr.lines().filter_map(|l|l.strip_prefix(if z{"ZOPRO_MSM_PHASES "}else{"MSM_PHASES "})).map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();assert_eq!(pp.len(),if j["arm"]=="ON"{n+3}else{0});phases+=pp.len();
 for p in &pp{let key=j["mode"].as_str().unwrap().to_owned();let size=p["rows"].as_array().unwrap().len();bounds.entry(key.clone()).and_modify(|v|*v=(*v).max(size)).or_insert(size);bounds.entry(format!("{key}-trace-bytes")).or_insert(p["trace_bytes"].as_u64().unwrap()as usize);if !z{let shape=p["rows"].as_array().unwrap().iter().map(|v|json!({"phase":v["phase"],"items":v["items"],"job_items":v["job_items"]})).collect::<Vec<_>>();geometry.entry(format!("{key}-{}",j["workers"])).or_default().insert(serde_json::to_string(&shape).unwrap());}}
 let pd=j["proof_dir"].as_str().unwrap();let h=sha(&format!("{pd}/0.proof"));assert_eq!(fs::metadata(format!("{pd}/0.proof")).unwrap().len(),164);assert!(exports.insert(h.clone()));let pubhash=sha(&format!("{pd}/0.public"));assert_eq!(pubhash,j["public_sha256"].as_str().unwrap());let v=fs::read_to_string(format!("{R}/run/verify-{name}/stdout.log")).unwrap();for binding in [format!("proof_sha256={h}"),format!("public_sha256={pubhash}"),format!("image_sha256={}",j["image_sha256"].as_str().unwrap())]{assert!(v.contains(&binding));}
 if j["panel"]=="main"{let row=rows.as_array().unwrap().iter().find(|r|r["job"]["name"]==name).unwrap();near(times.iter().sum::<f64>()/n as f64,row["mean_ms"].as_f64().unwrap());times.sort_by(f64::total_cmp);near(times[n/2],row["median_ms"].as_f64().unwrap());if j["arm"]=="REF"{let key=format!("{}-{}",j["mode"].as_str().unwrap(),j["workers"]);let f=faults.entry(key).or_insert(vec![0,0,0]);f[0]+=summary["minor_faults"].as_u64().unwrap();f[1]+=summary["voluntary_switches"].as_u64().unwrap();f[2]+=summary["involuntary_switches"].as_u64().unwrap();}if z{assert_eq!(summary["major_faults"],0);assert_eq!(summary["indexed_entries"],4*n);}}
 }
 assert_eq!(timed,10120);assert_eq!(phases,2940);assert_eq!(exports.len(),220);
 let before:BTreeSet<String>=serde_json::from_value(read("/home/ubuntu/src/zopro-perf-work/msm-full180/proof-sha256-after-preflight.json")).unwrap();let after:BTreeSet<String>=serde_json::from_value(read(&format!("{R}/proof-sha256-after-capture.json"))).unwrap();assert!(before.is_disjoint(&exports));assert_eq!(before.union(&exports).cloned().collect::<BTreeSet<_>>(),after);
 for gate in review["gates"].as_array().unwrap(){let pair=gate["ratio"].as_str().unwrap().split('/').collect::<Vec<_>>();let mut ratios=vec![];for b in 0..9{let find=|arm:&str|rows.as_array().unwrap().iter().find(|r|r["job"]["mode"]==gate["mode"]&&r["job"]["workers"]==gate["workers"]&&r["job"]["block"]==b&&r["job"]["arm"]==arm).unwrap()["median_ms"].as_f64().unwrap();ratios.push(find(pair[0])/find(pair[1]));}ratios.sort_by(f64::total_cmp);near(ratios[4],gate["median"].as_f64().unwrap());near(ratios[1],gate["interval"][0].as_f64().unwrap());near(ratios[7],gate["interval"][1].as_f64().unwrap());assert_eq!(gate["passed"],ratios[1]>=0.95&&ratios[7]<=1.05);}
 let out=json!({"passed":true,"raw_timed_samples":timed,"sdk_calls_including_primes":timed+220*3,"phase_records_including_primes":phases,"fresh_exports":exports,"max_rows_and_trace_sizes":bounds,"work_geometries_by_mode_workers":geometry.iter().map(|(k,v)|(k,v.iter().map(|s|serde_json::from_str::<Value>(s).unwrap()).collect::<Vec<_>>())).collect::<BTreeMap<_,_>>(),"reference_counts_minor_voluntary_involuntary_per459_requests":faults,"aeglos_major_faults_reported":false,"observer_gates_reproduced":16,"canonical_count":after.len()});
 assert!(!std::path::Path::new(&format!("{R}/audit.json")).exists());fs::write(format!("{R}/audit.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Raw audit passed10120 timed samples/2940phase records/220fresh exports/16gates; no SDK replay");
}
